  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--lustre-color) 9%, transparent) 34%,
    color-mix(in srgb, var(--lustre-color) 24%, transparent) 50%,
    color-mix(in srgb, var(--lustre-color) 9%, transparent) 66%,
    transparent
  );
  filter: blur(0.5px);
  opacity: 0.78;
  pointer-events: none;
  transform: skewX(-18deg) translateX(0);
}

.root[data-motion='loop'] .lustre {
  animation: lustre-pass var(--lustre-duration) cubic-bezier(0.4, 0, 0.2, 1)
    infinite;
}

.root[data-motion='hover'] .lustre {
  opacity: 0;
  transform: skewX(-18deg) translateX(0);
}

.root[data-motion='hover']:hover .lustre,
.root[data-motion='hover']:focus-visible .lustre {
  animation: lustre-hover 680ms cubic-bezier(0.2, 0, 0, 1) both;
}

.edge {
  position: absolute;
  z-index: -1;
  inset: 1px;
  border-radius: 11px;
  background: linear-gradient(
    110deg,
    rgb(255 255 255 / 4%),
    transparent 28%,
    transparent 72%,
    rgb(255 255 255 / 3%)
  );
  pointer-events: none;
}

.content {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 11px;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: -0.013em;
  white-space: nowrap;
}

.arrow {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.4;
  transition: transform 180ms cubic-bezier(0.2, 0, 0, 1);
}

.root:hover .arrow,
.root:focus-visible .arrow {
  transform: translateX(2px);
}

.root:disabled .lustre {
  animation: none;
}

.root:disabled .arrow {
  transform: none;
}

@keyframes lustre-pass {
  0%,
  54% {
    opacity: 0;
    transform: skewX(-18deg) translateX(0);
  }

  60% {
    opacity: 0.78;
  }

  82% {
    opacity: 0.78;
  }

  88%,
  100% {
    opacity: 0;
    transform: skewX(-18deg) translateX(560%);
  }
}

@keyframes lustre-hover {
  from {
    opacity: 0;
    transform: skewX(-18deg) translateX(0);
  }

  16% {
    opacity: 0.78;
  }

  84% {
    opacity: 0.78;
  }

  to {
    opacity: 0;
    transform: skewX(-18deg) translateX(560%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .arrow {
    transition: none;
  }

  .lustre,
  .root[data-motion='loop'] .lustre,
  .root[data-motion='hover']:hover .lustre,
  .root[data-motion='hover']:focus-visible .lustre {
    display: none;
    animation: none;
  }

  .root:active,
  .root:hover .arrow,
  .root:focus-visible .arrow {
    transform: none;
  }
}

@media (forced-colors: active) {
  .root {
    color: ButtonText;
    border-color: ButtonText;
    background: ButtonFace;
    box-shadow: none;
  }

  .lustre,
  .edge {
    display: none;
  }
}
